"use client";

import React, { useEffect, useState, createContext, useContext } from "react";
import { io } from "socket.io-client";
import { useAuth } from "./AuthContext";

const CallSocketContext = createContext(null);

export function CallSocketProvider({ children }) {
  const { user } = useAuth();
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    if (!user) return;

    // connect to the `/call` namespace
    const cs = io("http://localhost:5000/call", {
      path: "/socket.io",
      transports: ["websocket"],
      withCredentials: true,
    });
    setSocket(cs);

    cs.on("connect", () => {
      console.log("🟢 Call socket connected", cs.id);
      cs.emit("join_call", user.id);
    });

    return () => {
      cs.disconnect();
      setSocket(null);
    };
  }, [user]);

  return (
    <CallSocketContext.Provider value={socket}>
      {children}
    </CallSocketContext.Provider>
  );
}

export const useCallSocket = () => useContext(CallSocketContext);
